1	package store
2	
3	import (
4		"context"
5		"errors"
6		"path/filepath"
7		"sync"
8		"testing"
9	
10		"github.com/xjeey8iust/sen-sbom-inventory/internal/model"
11		"github.com/xjeey8iust/sen-sbom-inventory/internal/storetest"
12	)
13	
14	func openCountingStore(t *testing.T) (*Store, *storetest.Driver) {
15		t.Helper()
16		counted := storetest.Register()
17		st, err := OpenWithDriver(filepath.Join(t.TempDir(), "counted.db"), storetest.DriverName)
18		if err != nil {
19			t.Fatalf("open counting store: %v", err)
20		}
21		t.Cleanup(func() { st.Close() })
22		return st, counted
23	}
24	
25	func registerManifest(t *testing.T, st *Store, artifact, version string, comps []model.Component) *model.SBOM {
26		t.Helper()
27		got, created, err := st.Register(context.Background(), &model.SBOM{
28			Artifact: artifact, Version: version, Components: comps,
29		})
30		if err != nil {
31			t.Fatalf("register %s@%s: %v", artifact, version, err)
32		}
33		if !created {
34			t.Fatalf("register %s@%s: not created", artifact, version)
35		}
36		return got
37	}
38	
39	func twoComponents(aDeps []string) []model.Component {
40		return []model.Component{
41			{Coordinate: "a", License: "L-a", Dependencies: aDeps},
42			{Coordinate: "b", License: "L-b", Dependencies: []string{}},
43		}
44	}
45	
46	// TestListUsesAtMostFourSelects proves the query budget against the real
47	// driver: one manifest or a full hundred both take exactly four SELECTs
48	// (count, page rows, one batched components read, one batched dependencies
49	// read), and the two detail reads never return rows for anything outside the
50	// current page and requested artifact.
51	func TestListUsesAtMostFourSelects(t *testing.T) {
52		ctx := context.Background()
53	
54		t.Run("one manifest", func(t *testing.T) {
55			st, counted := openCountingStore(t)
56			registerManifest(t, st, "app", "1", []model.Component{
57				{Coordinate: "a", License: "A", Dependencies: []string{"b", "c"}},
58				{Coordinate: "b", License: "B", Dependencies: []string{"c"}},
59				{Coordinate: "c", License: "C", Dependencies: []string{}},
60			})
61			counted.Reset()
62	
63			items, total, err := st.List(ctx, "app", 1, 20)
64			if err != nil {
65				t.Fatalf("list: %v", err)
66			}
67			counters := counted.Snapshot()
68			if counters.Selects != 4 {
69				t.Fatalf("non-empty page ran %d SELECTs, want exactly 4", counters.Selects)
70			}
71			if total != 1 || len(items) != 1 {
72				t.Fatalf("total/items = %d/%d, want 1/1", total, len(items))
73			}
74			if counters.RowsByKind["count"] != 1 || counters.RowsByKind["sboms"] != 1 ||
75				counters.RowsByKind["components"] != 3 || counters.RowsByKind["dependencies"] != 3 {
76				t.Fatalf("unexpected row reads: %+v", counters.RowsByKind)
77			}
78		})
79	
80		t.Run("hundred manifests", func(t *testing.T) {
81			st, counted := openCountingStore(t)
82			const n = 100
83			for i := 0; i < n; i++ {
84				version := string(rune('0'+i/10)) + string(rune('0'+i%10))
85				registerManifest(t, st, "app", version, twoComponents([]string{"b"}))
86			}
87			// Another artifact sharing the same coordinates: its detail rows must
88			// never be read as part of an "app" page.
89			registerManifest(t, st, "other", "1", []model.Component{
90				{Coordinate: "a", License: "SECRET", Dependencies: []string{"b"}},
91				{Coordinate: "b", License: "SECRET", Dependencies: []string{"a"}},
92			})
93			counted.Reset()
94	
95			items, total, err := st.List(ctx, "app", 1, 100)
96			if err != nil {
97				t.Fatalf("list: %v", err)
98			}
99			counters := counted.Snapshot()
100			if counters.Selects != 4 {
101				t.Fatalf("100-item page ran %d SELECTs, want exactly 4", counters.Selects)
102			}
103			if total != n || len(items) != n {
104				t.Fatalf("total/items = %d/%d, want %d/%d", total, len(items), n, n)
105			}
106			if counters.RowsByKind["sboms"] != n ||
107				counters.RowsByKind["components"] != 2*n ||
108				counters.RowsByKind["dependencies"] != n {
109				t.Fatalf("detail reads escaped the page or artifact: %+v", counters.RowsByKind)
110			}
111			for _, item := range items {
112				if item.Artifact != "app" {
113					t.Fatalf("foreign manifest on page: %q", item.Artifact)
114				}
115				for _, c := range item.Components {
116					if c.License == "SECRET" {
117						t.Fatalf("component from another artifact leaked onto the page: %+v", c)
118					}
119				}
120			}
121		})
122	
123		t.Run("middle page", func(t *testing.T) {
