157		_, _, err := st.Register(ctx, &model.SBOM{
158			Artifact: "app", Version: "1",
159			Components: []model.Component{
160				{Coordinate: "a", License: "CHANGED", Dependencies: []string{"b"}},
161				{Coordinate: "b", License: "L-b", Dependencies: []string{}},
162			},
163		})
164		if !errors.Is(err, model.ErrConflict) {
165			t.Fatalf("error = %v, want model.ErrConflict", err)
166		}
167		if strings.Contains(err.Error(), "forced rollback failure") {
168			t.Fatalf("cleanup error replaced the business error: %v", err)
169		}
170	
171		// An identical replay still returns the original record afterwards, so the
172		// connection stayed usable and the record is unchanged.
173		replayed, created, err := st.Register(ctx, &model.SBOM{
174			Artifact: "app", Version: "1", Components: twoComponentsWithDep(),
175		})
176		if err != nil || created {
177			t.Fatalf("replay after failed cleanup: err=%v created=%v", err, created)
178		}
