//     empty array, never null;
//   - coordinates must be unique after trimming; a component's dependency
//     targets must be non-empty, unique, not the component itself and must name
//     a coordinate present in the same manifest. Dependencies may point at
//     components listed later, and non-self cycles are allowed;
//   - licenses and coordinate formats are not otherwise inspected.
//
// On success the returned *model.SBOM is normalized (components and each
// component's dependencies sorted ascending by coordinate string) and carries
// the zero ID: it has not been registered anywhere. Duplicates are rejected
// rather than merged.
//
// Every rejection returns an error that errors.Is recognizes as
// model.ErrInvalidInput, together with a nil manifest. raw is never modified,
// no storage is accessed, and repeated calls never share state or results.
func ParseRegistration(raw []byte) (*model.SBOM, error) {
	var req registerInput
	if err := json.Unmarshal(raw, &req); err != nil {
		return nil, model.ErrInvalidInput
	}
	// The body must resolve to exactly one JSON value: "{} {}" and
	// "{} garbage" are rejected instead of silently keeping the first object.
	if hasTrailingValue(raw) {
		return nil, model.ErrInvalidInput
	}
	if req.Artifact == nil || req.Version == nil || req.Components == nil {
		return nil, model.ErrInvalidInput
	}

	artifact := strings.TrimSpace(*req.Artifact)
	version := strings.TrimSpace(*req.Version)
	if artifact == "" || version == "" {
		return nil, model.ErrInvalidInput
	}

	coordinates := make(map[string]struct{}, len(req.Components))
	for _, comp := range req.Components {
		coordinates[comp.coordinate] = struct{}{}
	}

	components := make([]model.Component, len(req.Components))
	for i, comp := range req.Components {
		for _, dep := range comp.deps {
			if _, ok := coordinates[dep]; !ok {
				return nil, model.ErrInvalidInput
			}
		}
		sort.Strings(comp.deps)
		components[i] = model.Component{
			Coordinate:   comp.coordinate,
			License:      comp.license,
			Dependencies: comp.deps,
		}
	}
	sort.Slice(components, func(i, j int) bool { return components[i].Coordinate < components[j].Coordinate })

	return &model.SBOM{
		Artifact:   artifact,
		Version:    version,
		Components: components,
	}, nil
}

// hasTrailingValue reports whether anything but whitespace follows the first
// top-level JSON value in body. A single json.Unmarshal already rejects such
// trailing bytes today; the explicit decoder check keeps the one-value
// contract independent of that detail.
func hasTrailingValue(body []byte) bool {
	dec := json.NewDecoder(bytes.NewReader(body))
	var first json.RawMessage
	if err := dec.Decode(&first); err != nil {
		return false // The first decode already failed; the caller rejects it.
	}
	var next json.RawMessage
	return dec.Decode(&next) == nil
}

package api

import (
	"errors"
	"io"
	"net/http"
	"strconv"
	"strings"

	"github.com/gin-gonic/gin"

	"github.com/xjeey8iust/sen-sbom-inventory/internal/manifest"
	"github.com/xjeey8iust/sen-sbom-inventory/internal/model"
)

// errMalformed is returned by the request decoders for every shape the API
// contract rejects. The single error keeps SQL, paths and internals out of the
// client-visible message.
var errMalformed = errors.New("malformed SBOM request")

func (h *sbomHandlers) register(c *gin.Context) {
	body, err := io.ReadAll(c.Request.Body)
	if err != nil {
		writeAPIError(c, http.StatusBadRequest, invalidInputCode, invalidInputMessage)
		return
	}

	// Parsing, validation and normalization are HTTP/storage-independent: the
	// same entry plain Go callers use, so the on-wire rules and the library
	// rules can never drift apart. A successful parse yields an unregistered
	// manifest with the zero ID; the store assigns the ID.
	sbom, err := manifest.ParseRegistration(body)
	if err != nil {
		writeAPIError(c, http.StatusBadRequest, invalidInputCode, invalidInputMessage)
		return
	}

	sbom, _, err = h.store.Register(c.Request.Context(), sbom)
	if err != nil {
		writeStoreError(c, err)
		return
	}
	c.JSON(http.StatusCreated, sbom)
}

type listResponse struct {
	Items    []*model.SBOM `json:"items"`
	Total    int           `json:"total"`
	Page     int           `json:"page"`
	PageSize int           `json:"pageSize"`
}

func (h *sbomHandlers) list(c *gin.Context) {
	artifact := strings.TrimSpace(c.Query("artifact"))
	if artifact == "" {
		writeAPIError(c, http.StatusBadRequest, invalidInputCode, invalidInputMessage)
		return
	}
	page, err := positiveQuery(c, "page", 1)
	if err != nil {
		writeAPIError(c, http.StatusBadRequest, invalidInputCode, invalidInputMessage)
		return
	}
	pageSize, err := positiveQuery(c, "pageSize", 20)
	if err != nil || pageSize > 100 {
		writeAPIError(c, http.StatusBadRequest, invalidInputCode, invalidInputMessage)
		return
	}

	items, total, err := h.store.List(c.Request.Context(), artifact, page, pageSize)
	if err != nil {
		writeStoreError(c, err)
		return
	}
	c.JSON(http.StatusOK, listResponse{Items: items, Total: total, Page: page, PageSize: pageSize})
}

// positiveQuery parses an optional query parameter that, when present, must be
// a decimal positive integer (digits only, no sign, no spaces).
func positiveQuery(c *gin.Context, name string, fallback int) (int, error) {
	raw, present := c.GetQuery(name)
	if !present {
		return fallback, nil
	}
	if raw == "" || len(raw) > 10 {
		return 0, errMalformed
	}
	for i := 0; i < len(raw); i++ {
		if raw[i] < '0' || raw[i] > '9' {
			return 0, errMalformed
		}
	}
	value, err := strconv.Atoi(raw)
	if err != nil || value <= 0 {
		return 0, errMalformed
	}
	return value, nil
}

const (
	invalidInputCode    = "InvalidSbomInputError"
	conflictCode        = "SbomConflictError"
	notFoundCode        = "SbomNotFoundError"
	storageCode         = "storage_unavailable"
	invalidInputMessage = "request is not a valid SBOM manifest"
	conflictMessage     = "an SBOM with different content already exists for this artifact and version"
	notFoundMessage     = "no SBOM is registered for this artifact and version"
	storageMessage      = "database is not available"
)

func writeAPIError(c *gin.Context, status int, code, message string) {
	c.JSON(status, gin.H{"error": gin.H{"code": code, "message": message}})
}

// writeStoreError maps the store's sentinel errors to the contracted status
// codes. Every other storage failure is reported generically as 503.
func writeStoreError(c *gin.Context, err error) {
	switch {
	case errors.Is(err, model.ErrConflict):
		writeAPIError(c, http.StatusConflict, conflictCode, conflictMessage)
	case errors.Is(err, model.ErrNotFound):
		writeAPIError(c, http.StatusNotFound, notFoundCode, notFoundMessage)
	case errors.Is(err, model.ErrStorageUnavailable):
		writeAPIError(c, http.StatusServiceUnavailable, storageCode, storageMessage)
	default:
		writeAPIError(c, http.StatusServiceUnavailable, storageCode, storageMessage)
	}
}

package api

import (
	"net/http"

	"github.com/gin-gonic/gin"

	"github.com/xjeey8iust/sen-sbom-inventory/internal/store"
)

// sbomHandlers bundles the HTTP handlers with their storage dependency.
type sbomHandlers struct {
	store *store.Store
}

// NewRouter wires the public HTTP surface. Every entry keeps the error shape
// the service contract in README.md describes.
func NewRouter(st *store.Store) *gin.Engine {
	gin.SetMode(gin.ReleaseMode)
	router := gin.New()
	router.Use(gin.Recovery())

	h := &sbomHandlers{store: st}

	router.GET("/healthz", func(c *gin.Context) {
		if err := st.Ping(); err != nil {
			c.JSON(http.StatusServiceUnavailable, gin.H{"error": gin.H{"code": "storage_unavailable", "message": "database is not available"}})
			return
		}
		c.JSON(http.StatusOK, gin.H{"status": "ok", "database": "ok"})
	})

	router.POST("/sboms", h.register)
	router.GET("/sboms", h.list)
	router.GET("/sboms/diff", h.diff)

	router.NoRoute(func(c *gin.Context) {
		c.JSON(http.StatusNotFound, gin.H{"error": gin.H{"code": "route_not_found", "message": "no route matches this path"}})
	})
	return router
}

